// Image pipeline guard (run: node scripts/check-image-loader.mjs).
//
// 1. URL contract with the server: src/lib/spaces-image.js must derive the
//    same variant URLs as server.me services/storage.js. The vectors file is
//    generated by the server's test suite (tests/batch-s/image-variants.test.js,
//    WRITE_VECTORS=1) and copied here; a naming change on one side that is
//    not mirrored fails this script.
// 2. Coverage: every next/image (or raw <img>) that shows a listing photo or
//    a profile picture in code reachable from the app must go through
//    MediaImage / MediaImg (src/components/ui/media-image.jsx) or the shared
//    AvatarImage — otherwise its bytes would come from /_next/image (Vercel
//    image optimization, the quota this pipeline removes the site from).
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const lib = await import(pathToFileURL(path.join(root, "src/lib/spaces-image.js")).href);
const problems = [];

// --- 1. vectors -------------------------------------------------------------
const vectors = JSON.parse(fs.readFileSync(path.join(root, "scripts/fixtures/image-variant-vectors.json"), "utf8"));
const canon = (u) => {
  const x = new URL(u);
  return `${x.hostname}${decodeURIComponent(x.pathname)}`;
};
if (vectors.set !== lib.VARIANT_SET) problems.push(`variant set: site ${lib.VARIANT_SET} vs server ${vectors.set}`);
if (JSON.stringify(vectors.widths) !== JSON.stringify(lib.VARIANT_WIDTHS)) problems.push(`variant widths: site ${lib.VARIANT_WIDTHS} vs server ${vectors.widths}`);
let checked = 0;
for (const v of vectors.vectors) {
  for (const [w, expected] of Object.entries(v.byWidth)) {
    const got = lib.variantUrl(v.src, Number(w));
    checked += 1;
    if (!got || canon(got) !== canon(expected)) problems.push(`variantUrl(${v.src}, ${w}) = ${got} ≠ ${expected}`);
  }
  if (!lib.isSpacesUrl(v.src)) problems.push(`isSpacesUrl(${v.src}) should be true`);
}
for (const src of vectors.notOurs) {
  if (lib.parseSpacesUrl(src) !== null) problems.push(`parseSpacesUrl(${src}) should be null`);
  if (lib.spacesLoader({ src, width: 640 }) !== src) problems.push(`spacesLoader must pass ${src} through unchanged`);
}
// the loader never returns a master and never a URL that is not on the CDN host
for (const v of vectors.vectors) {
  const out = lib.spacesLoader({ src: v.src, width: 99999 });
  if (!/\.cdn\.digitaloceanspaces\.com\/.+\/v[0-9]+\/w[0-9]+\.webp$/.test(out)) problems.push(`loader returned a non-variant for ${v.src}: ${out}`);
}

// --- 2. coverage --------------------------------------------------------------
const SRC = path.join(root, "src");
const EXT = [".tsx", ".ts", ".jsx", ".js"];
function resolveImport(from, spec) {
  let base;
  if (spec.startsWith("@/")) base = path.join(SRC, spec.slice(2));
  else if (spec.startsWith(".")) base = path.resolve(path.dirname(from), spec);
  else return null;
  for (const candidate of [base, ...EXT.map((e) => base + e), ...EXT.map((e) => path.join(base, "index" + e))]) {
    if (fs.existsSync(candidate) && fs.statSync(candidate).isFile()) return candidate;
  }
  return null;
}
// reachable modules: every page/layout/template/route under src/app plus middleware, following imports
const reachable = new Set();
const queue = [];
(function walk(d) {
  for (const e of fs.readdirSync(d, { withFileTypes: true })) {
    const p = path.join(d, e.name);
    if (e.isDirectory()) walk(p);
    else if (/^(page|layout|template|loading|error|not-found|default)\.(jsx?|tsx?)$/.test(e.name)) queue.push(p);
  }
})(path.join(SRC, "app"));
for (const m of ["middleware.ts", "middleware.js"]) if (fs.existsSync(path.join(SRC, m))) queue.push(path.join(SRC, m));
while (queue.length) {
  const f = queue.pop();
  if (reachable.has(f)) continue;
  reachable.add(f);
  const text = fs.readFileSync(f, "utf8");
  for (const m of text.matchAll(/(?:import|export)\s[^"'`]*?from\s*["']([^"']+)["']|import\s*\(\s*["']([^"']+)["']\s*\)|import\s+["']([^"']+)["']/g)) {
    const target = resolveImport(f, m[1] || m[2] || m[3]);
    if (target && !reachable.has(target)) queue.push(target);
  }
}

const MEDIA_SRC = /photos|profilePicture|avatar|propertyImage|hostImage|\.image\b|images\[|\.url\b|digitaloceanspaces/i;
const NOT_MEDIA = /icon|logo|placeholder|\/images\/|\/carousel\//i;
// Media-looking fields that come from static data in the repo (blog posts,
// the experiences catalogue, /images/tour/*): not host uploads, so the
// default next/image path is the intended one. Each entry must still exist.
const STATIC_DATA = new Set([
  "src/app/(landing)/blogs/page.tsx",
  "src/app/(landing)/experience/page.tsx",
  "src/app/(landing)/experience/components/review.tsx",
  "src/components/experiences/share-dialog.jsx",
  "src/components/experience-block.tsx",
  "src/components/experience-hero.jsx",
]);
for (const f of STATIC_DATA) if (!fs.existsSync(path.join(root, f))) problems.push(`allowlist entry no longer exists: ${f}`);
let tags = 0;
let mediaTags = 0;
for (const f of reachable) {
  if (STATIC_DATA.has(path.relative(root, f).split(path.sep).join("/"))) continue;
  const text = fs.readFileSync(f, "utf8");
  const usesNextImage = /from\s*["']next\/image["']/.test(text);
  // strip comments so commented-out markup is not counted
  const code = text.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "").replace(/\{\/\*[\s\S]*?\*\/\}/g, "");
  for (const m of code.matchAll(/<(Image|img|MediaImage|MediaImg)\b([\s\S]*?)(\/>|>)/g)) {
    const [, tag, attrs] = m;
    const src = (attrs.match(/\bsrc=\s*(\{[\s\S]*?\}|"[^"]*"|'[^']*')/) || [])[1] || "";
    tags += 1;
    const isMedia = MEDIA_SRC.test(src) && !NOT_MEDIA.test(src);
    if (!isMedia) continue;
    mediaTags += 1;
    const line = code.slice(0, m.index).split("\n").length;
    const rel = path.relative(root, f).split(path.sep).join("/");
    if (tag === "Image" && usesNextImage) problems.push(`${rel}:${line} <Image src=${src.replace(/\s+/g, " ").slice(0, 60)}> shows media through next/image — use MediaImage`);
    if (tag === "img") problems.push(`${rel}:${line} <img src=${src.replace(/\s+/g, " ").slice(0, 60)}> shows media as a raw img — use MediaImg`);
  }
}

console.log(`[image-loader] vectors: ${checked} widths across ${vectors.vectors.length} sources OK; not-ours: ${vectors.notOurs.length}`);
console.log(`[image-loader] coverage: ${reachable.size} reachable modules, ${tags} image tags, ${mediaTags} media tags`);
if (problems.length) {
  for (const p of problems) console.error("  ✗ " + p);
  process.exit(1);
}
console.log("[image-loader] OK");
